typedef long long ll;

static ll pow3[31];

/*
A cell (x,y) is white iff for every ternary digit position,
not both digits are 1 simultaneously.
Coordinates here are 0-based.
*/
static int is_white(ll x, ll y) {
    while (x > 0 || y > 0) {
        if (x % 3 == 1 && y % 3 == 1) return 0;
        x /= 3;
        y /= 3;
    }
    return 1;
}

/*
For two white cells inside the same level-k block [0,3^k)^2,
distance can be computed recursively.

Let S = 3^(k-1), and split into 3x3 subblocks.
If both points are in the same non-center subblock, recurse.

Otherwise, any path must go through the "frame" around the central black block.
That frame is connected, and the shortest path is Manhattan distance unless
the straight rectangle crosses the black center. In that case one must detour
around one side of the central SxS hole, costing extra 2 * min(horizontal gap
to left/right side, vertical gap to bottom/top side) at this scale.

This logic is applied recursively by first reducing while both are in same child.
*/

static ll dist_rec(ll x1, ll y1, ll x2, ll y2, int k) {
    while (k > 0) {
        ll S = pow3[k - 1];
        int bx1 = (int)(x1 / S), by1 = (int)(y1 / S);
        int bx2 = (int)(x2 / S), by2 = (int)(y2 / S);

        if (bx1 == bx2 && by1 == by2) {
            /* same child block; must be non-center since both white */
            x1 %= S; y1 %= S;
            x2 %= S; y2 %= S;
            k--;
            continue;
        }

        ll man = llabs(x1 - x2) + llabs(y1 - y2);

        /*
        Central black square at this level is:
        [S,2S) x [S,2S)
        A Manhattan shortest path exists iff we can choose horizontal-first or
        vertical-first without entering the open black square.

        Rectangle crossing conditions:
        x-interval intersects [S,2S) and y-interval intersects [S,2S).
        Then every monotone path crosses the hole, requiring detour.
        */
        ll minx = x1 < x2 ? x1 : x2;
        ll maxx = x1 > x2 ? x1 : x2;
        ll miny = y1 < y2 ? y1 : y2;
        ll maxy = y1 > y2 ? y1 : y2;

        int crossX = (minx < 2 * S && maxx >= S);
        int crossY = (miny < 2 * S && maxy >= S);

        if (!(crossX && crossY)) return man;

        /*
        Need to go around one side of the hole.
        Extra cost is twice the minimum distance to one of the four sides
        of the hole measured in the corresponding dimension:
          left side x = S-1 / right side x = 2S
          bottom side y = S-1 / top side y = 2S
        In terms of coordinates, equivalent extra:
          2 * min(
              min(|x1-(S-1)|, |x1-2S|) ??? not enough for both points
          )
        More simply for axis-aligned rectangle around a rectangular hole,
        shortest detour extra equals
          2 * min( minx_to_left + right? )
        But because both endpoints are outside and rectangle spans the hole,
        one chooses a side completely outside the hole:
          go left of x=S, or right of x=2S-1, or below y=S, or above y=2S-1.
        The extra over Manhattan is:
          2 * min( minx - S + 1? , 2S - 1 - maxx + 1? , miny - S + 1? , 2S - 1 - maxy + 1? )
        After simplification in lattice-cell graph with cell centers, this becomes:
          2 * min( S - minx, maxx - (2S - 1), S - miny, maxy - (2S - 1) )
        among the applicable nonnegative quantities.
        Since crossX/crossY hold, these are >=1 in the spanning directions.
        */
        ll extra_left   = S - minx;
        ll extra_right  = maxx - (2 * S - 1);
        ll extra_down   = S - miny;
        ll extra_up     = maxy - (2 * S - 1);

        ll extra = extra_left;
        if (extra_right < extra) extra = extra_right;
        if (extra_down < extra) extra = extra_down;
        if (extra_up < extra) extra = extra_up;

        return man + 2 * extra;
    }
    return 0;
}

