#include <bits/stdc++.h>
using namespace std;
using int64 = long long;

// Returns the level of the smallest square containing (x,y) that is white.
// For level K, coordinates are 1-indexed in [1, 3^K].
int64 level_of(int64 x, int64 y, int64 K) {
    int64 sz = 1;
    for (int64 i = 0; i < K; i++) sz *= 3;
    int64 block = sz / 3;
    int64 cx = (x - 1) / block;
    int64 cy = (y - 1) / block;
    if (cx == 1 && cy == 1) return K;  // black at this level
    if (K == 0) return 0;
    int64 nx = (x - 1) % block + 1;
    int64 ny = (y - 1) % block + 1;
    return level_of(nx, ny, K - 1);
}

// Get coordinates relative to the smallest white block containing it
pair<int64, int64> normalize(int64 x, int64 y, int64 L) {
    int64 sz = 1;
    for (int64 i = 0; i < L; i++) sz *= 3;
    int64 block = sz / 3;
    int64 cx = (x - 1) / block;
    int64 cy = (y - 1) / block;
    int64 nx = (x - 1) % block + 1;
    int64 ny = (y - 1) % block + 1;
    return {nx, ny};
}

// Find distance between two white squares
int64 dist(int64 a, int64 b, int64 c, int64 d, int64 K) {
    int64 la = level_of(a, b, K);
    int64 lc = level_of(c, d, K);
    int64 L = min(la, lc);

    // Go down to level L for both
    auto norm_a = normalize(a, b, L);
    auto norm_c = normalize(c, d, L);
    int64 x1 = norm_a.first, y1 = norm_a.second;
    int64 x2 = norm_c.first, y2 = norm_c.second;

    if (L == 0) {
        return abs(x1 - x2) + abs(y1 - y2);
    }

    int64 sz = 1;
    for (int64 i = 0; i < L; i++) sz *= 3;
    int64 block = sz / 3;

    int64 cx1 = (x1 - 1) / block;
    int64 cy1 = (y1 - 1) / block;
    int64 cx2 = (x2 - 1) / block;
    int64 cy2 = (y2 - 1) / block;

    // If in same sub-square, recurse
    if (cx1 == cx2 && cy1 == cy2) {
        return dist((a - 1) % block + 1, (b - 1) % block + 1,
                    (c - 1) % block + 1, (d - 1) % block + 1, L - 1);
    }

    // Else, we can go around the center
    int64 dx = abs(cx1 - cx2);
    int64 dy = abs(cy1 - cy2);
    int64 ans = (dx + dy) * block;

    // Add distances to edges of current sub-squares
    auto to_edge = [&](int64 x, int64 y, int64 cx, int64 cy) -> int64 {
        int64 subx = (x - 1) % block + 1;
        int64 suby = (y - 1) % block + 1;
        int64 res = 0;
        if (cx == 0) res += subx - 1;
        else if (cx == 2) res += block - subx;
        else {
            res += min(subx - 1, block - subx);
        }
        if (cy == 0) res += suby - 1;
        else if (cy == 2) res += block - suby;
        else {
            res += min(suby - 1, block - suby);
        }
        return res;
    };

    ans += to_edge(a, b, cx1, cy1);
    ans += to_edge(c, d, cx2, cy2);
    return ans;
}

