#include <bits/stdc++.h>
using namespace std;

using int64 = long long;
using i128 = __int128_t;

static i128 pw3[31];

struct Node {
    int k;          // level
    i128 x, y;      // top-left corner of this 3^k x 3^k block
};

static inline bool inRange(i128 v, i128 l, i128 r) {
    return l <= v && v < r;
}

// Find the smallest-level fractal block that contains both points and whose
// center 1/3 subgrid separates them (i.e. they are not in the same child block).
static Node lcaBlock(i128 ax, i128 ay, i128 bx, i128 by) {
    i128 x = 0, y = 0;
    int k = 30;
    while (k > 0) {
        i128 len = pw3[k - 1];
        int ia = (int)((ax - x) / len);
        int ja = (int)((ay - y) / len);
        int ib = (int)((bx - x) / len);
        int jb = (int)((by - y) / len);
        if (ia == ib && ja == jb && !(ia == 1 && ja == 1)) {
            x += (i128)ia * len;
            y += (i128)ja * len;
            --k;
        } else {
            break;
        }
    }
    return {k, x, y};
}

// Distance from point (px,py) inside a white part of this level-k block
// to the boundary side 'side' of the block, where side:
// 0=up,1=down,2=left,3=right.
// The path must stay inside white squares of this block.
static i128 distToSide(int k, i128 x, i128 y, i128 px, i128 py, int side) {
    if (k == 0) return 0;

    i128 len = pw3[k - 1];
    int ix = (int)((px - x) / len);
    int iy = (int)((py - y) / len);

    // same child as point
    i128 cx = x + (i128)ix * len;
    i128 cy = y + (i128)iy * len;

    // If the desired outer side belongs to this child, recurse directly.
    if (side == 0 && ix == 0) return distToSide(k - 1, cx, cy, px, py, side);
    if (side == 1 && ix == 2) return distToSide(k - 1, cx, cy, px, py, side);
    if (side == 2 && iy == 0) return distToSide(k - 1, cx, cy, px, py, side);
    if (side == 3 && iy == 2) return distToSide(k - 1, cx, cy, px, py, side);

    // Otherwise we must first reach one of the sides of the current child
    // that faces a non-center neighboring child, then cross that border.
    i128 best = -1;

    auto relax = [&](i128 val) {
        if (best == -1 || val < best) best = val;
    };

    // Move upward to child (ix-1, iy), valid iff ix>0 and neighbor not center.
    if (ix > 0 && !(ix - 1 == 1 && iy == 1)) {
        relax(distToSide(k - 1, cx, cy, px, py, 0) + 1 +
              distToSide(k - 1, x + (i128)(ix - 1) * len, cy,
                         x + (i128)(ix - 1) * len, cy, side));
    }
    // downward
    if (ix < 2 && !(ix + 1 == 1 && iy == 1)) {
        relax(distToSide(k - 1, cx, cy, px, py, 1) + 1 +
              distToSide(k - 1, x + (i128)(ix + 1) * len, cy,
                         x + (i128)(ix + 1) * len, cy, side));
    }
    // left
    if (iy > 0 && !(ix == 1 && iy - 1 == 1)) {
        relax(distToSide(k - 1, cx, cy, px, py, 2) + 1 +
              distToSide(k - 1, cx, y + (i128)(iy - 1) * len,
                         cx, y + (i128)(iy - 1) * len, side));
    }
    // right
    if (iy < 2 && !(ix == 1 && iy + 1 == 1)) {
        relax(distToSide(k - 1, cx, cy, px, py, 3) + 1 +
              distToSide(k - 1, cx, y + (i128)(iy + 1) * len,
                         cx, y + (i128)(iy + 1) * len, side));
    }

    return best;
}

// Convert i128 to string
static string toString(i128 x) {
    if (x == 0) return "0";
    bool neg = x < 0;
    if (neg) x = -x;
    string s;
    while (x > 0) {
        int d = (int)(x % 10);
        s.push_back('0' + d);
        x /= 10;
    }
    if (neg) s.push_back('-');
    reverse(s.begin(), s.end());
    return s;
}

