            return v;
        };

        // Explicitly enumerate the four corners around the center hole:
        // corner 0: between top-left / top-middle / middle-left
        // uses bottom side for upper child, right side for left child
        // represented by target outer sides of the children's blocks.
        vector<pair<int,int>> cornerNeedA, cornerNeedB;

        i128 ans = -1;
        auto upd = [&](i128 val) {
            if (ans == -1 || val < ans) ans = val;
        };

        // Four corner cells around the center hole:
        // (1,1) hole occupies rows/cols [len,2len). Corners are:
        // TL corner cell adjacent from child (0,0),(0,1),(1,0)
        // TR from (0,1),(0,2),(1,2)
        // BL from (1,0),(2,0),(2,1)
        // BR from (1,2),(2,1),(2,2)
        struct Corner {
            int ci, cj;
            vector<pair<int,int>> entries; // child position -> side to reach corner, encoded as flattened (i*3+j, side)
        };
        vector<Corner> corners = {
            {1,1, {{0*3+0,1},{0*3+1,2},{1*3+0,0}}},
            {1,1, {{0*3+1,3},{0*3+2,1},{1*3+2,0}}},
            {1,1, {{1*3+0,1},{2*3+0,3},{2*3+1,2}}},
            {1,1, {{1*3+2,1},{2*3+1,3},{2*3+2,2}}}
        };

        for (auto &cor : corners) {
            int sideA = -1, sideB = -1;
            for (auto &e : cor.entries) {
                int pos = e.first, sd = e.second;
                if (pos == ia * 3 + ja) sideA = sd;
                if (pos == ib * 3 + jb) sideB = sd;
            }
            if (sideA == -1 || sideB == -1) continue;

            i128 da = distToSide(t.k - 1, t.x + (i128)ia * len, t.y + (i128)ja * len, ax, ay, sideA);
            i128 db = distToSide(t.k - 1, t.x + (i128)ib * len, t.y + (i128)jb * len, bx, by, sideB);

            // From each child boundary to the corner cell is 0 additional inside that child:
            // distToSide already lands on a boundary cell of the child. The two resulting cells
            // meet at the same corner cell in the parent arrangement, so total is additive.
            upd(da + db);
        }

        cout << toString(ans) << '\n';
    }
    return 0;
}

import java.io.*;
import java.util.*;

public class Main {
    static long[] size; // size[k] = 3^k

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int Q = Integer.parseInt(br.readLine().trim());

        // Precompute powers of 3 up to 3^30
        size = new long[31];
        size[0] = 1;
        for (int i = 1; i <= 30; i++) {
            size[i] = size[i-1] * 3;
        }

        StringBuilder sb = new StringBuilder();
        for (int q = 0; q < Q; q++) {
            StringTokenizer st = new StringTokenizer(br.readLine());
            long a = Long.parseLong(st.nextToken());
            long b = Long.parseLong(st.nextToken());
            long c = Long.parseLong(st.nextToken());
            long d = Long.parseLong(st.nextToken());

            // Convert to 0-based
            a--; b--; c--; d--;

            long dist = bfsDist(a, b, c, d);
            sb.append(dist).append("\n");
        }
        System.out.print(sb);
    }

    // BFS over white cells in fractal of level 30 (or enough to cover coordinates)
    static long bfsDist(long x1, long y1, long x2, long y2) {
        // Since the fractal is huge, we cannot BFS directly.
        // We use a recursive approach to compute Manhattan-like distance in fractal.
        return fractalDist(x1, y1, x2, y2, 30);
    }

    // Recursive distance in fractal of level K (size = 3^K)
    static long fractalDist(long x1, long y1, long x2, long y2, int K) {
        if (K == 0) {
            return Math.abs(x1 - x2) + Math.abs(y1 - y2);
        }

        long block = size[K-1]; // size of subgrids (3^{K-1})

        // Find which subgrid each point is in (0..2 for x and y)
        int bx1 = (int)(x1 / block);
        int by1 = (int)(y1 / block);
        int bx2 = (int)(x2 / block);
        int by2 = (int)(y2 / block);

        // If both points in same subgrid, go deeper
        if (bx1 == bx2 && by1 == by2) {
            // But if subgrid is black center (1,1) for K>=1, that means they are not white -> shouldn't happen per input
            if (bx1 == 1 && by1 == 1) {
                // Actually center is black, so white cells cannot be here; but input guarantees white.
                // This case would only occur for K=0 or if center is not black (K=0)
                // For safety:
                return Math.abs(x1 - x2) + Math.abs(y1 - y2);
            }
            return fractalDist(x1 % block, y1 % block, x2 % block, y2 % block, K-1);
        }

        // If both are in white subgrids (not center), we need to go via center edges.
        // The minimal path will go through the "white corridors" between subgrids.
        // We can compute using a BFS over 8 subgrids (excluding center) but with distance contributions.
        // Since K <= 30 and Q <= 10000, we can simulate BFS on coarse grid of subgrids.

        // Coarse BFS over the 3x3 subgrids (only white ones: all except (1,1))
        long[][] dist = new long[3][3];
        for (int i = 0; i < 3; i++) Arrays.fill(dist[i], Long.MAX_VALUE);
        dist[bx1][by1] = 0;
        Queue<int[]> queue = new LinkedList<>();
        queue.add(new int[]{bx1, by1});
        int[] dx = {1, -1, 0, 0};
        int[] dy = {0, 0, 1, -1};

        while (!queue.isEmpty()) {
            int[] cur = queue.poll();
            int cx = cur[0], cy = cur[1];
            for (int d = 0; d < 4; d++) {
                int nx = cx + dx[d];
                int ny = cy + dy[d];
                if (nx < 0 || nx >= 3 || ny < 0 || ny >= 3) continue;
                if (nx == 1 && ny == 1) continue; // black center
                if (dist[nx][ny] > dist[cx][cy] + block) {
                    dist[nx][ny] = dist[cx][cy] + block;
                    queue.add(new int[]{nx, ny});
                }
            }
        }

        long coarseDist = dist[bx2][by2];
        if (coarseDist == Long.MAX_VALUE) {
            // Should not happen for white cells
            return Math.abs(x1 - x2) + Math.abs(y1 - y2);
        }

        // Add distances from points to the borders of their subgrids towards the exit direction
        long fromStart = distToBorder(x1 % block, y1 % block, bx1, by1, bx2, by2, block);
        long toEnd = distToBorder(x2 % block, y2 % block, bx2, by2, bx1, by1, block);

        // The path: start -> border of start subgrid (towards next subgrid) -> ... -> border of end subgrid -> end
        // But coarseDist already includes the full block steps between subgrid centers.
        // We need to replace center-to-center distances with border-to-border distances.
        // Actually coarseDist is sum of block lengths between centers.
        // To go from start point to end point, we go: start -> border of start subgrid (in direction of path),
        // then cross subgrid boundaries, then border of end subgrid -> end.
        // Crossing each subgrid boundary adds 0 extra because boundaries touch.
        // So total = fromStart + (coarseDist - block) + toEnd? Let's derive carefully.

        // Let the path go through subgrids S0, S1, ..., Sm where S0 = (bx1,by1), Sm = (bx2,by2).
        // For each step Si -> Si+1, we cross from border of Si to border of Si+1 (distance 0).
        // Inside each intermediate subgrid, we go from entry border to exit border.
        // The distance inside intermediate subgrid is exactly block (since we go straight across).
        // For S0, we go from start to exit border; for Sm, from entry border to end.
        // So total = distStartToExit + (m-1)*block + distEntryToEnd.
        // But coarseDist = m * block (since each step moves block distance center-to-center).
        // So total = distStartToExit + distEntryToEnd + coarseDist - block.

        long distStartToExit = distInsideToBorder(x1 % block, y1 % block, bx1, by1, bx2, by2, block, K-1);
        long distEntryToEnd = distInsideToBorder(x2 % block, y2 % block, bx2, by2, bx1, by1, block, K-1);

        return distStartToExit + distEntryToEnd + coarseDist - block;
    }

    // Distance from point inside subgrid (local coords) to the border in the direction towards target subgrid
    static long distInsideToBorder(long lx, long ly, int subX, int subY, int targetSubX, int targetSubY, long block, int K) {
        // Determine exit direction: towards target subgrid
        int dirX = Integer.signum(targetSubX - subX);
        int dirY = Integer.signum(targetSubY - subY);

        // If same subgrid, should not call this
        if (dirX == 0 && dirY == 0) return 0;

        long dist = 0;
        // Move in x direction if needed
        if (dirX != 0) {
            if (dirX > 0) {
                dist += (block - 1 - lx);
            } else {
                dist += lx;
            }
        }
        if (dirY != 0) {
            if (dirY > 0) {
                dist += (block - 1 - ly);
            } else {
                dist += ly;
            }
        }
        // If moving diagonally, the path goes L-shaped, so sum is correct.
        return dist;
    }

    // Legacy helper not used
    static long distToBorder(long lx, long ly, int subX, int subY, int targetSubX, int targetSubY, long block) {
        return distInsideToBorder(lx, ly, subX, subY, targetSubX, targetSubY, block, 0);
    }
}

import java.util.*;
import java.io.*;

public class Main {
    static long[] pow3 = new long[31];

    public static void main(String[] args) throws IOException {
        pow3[0] = 1;
        for (int i = 1; i <= 30; i++) pow3[i] = pow3[i-1] * 3;

        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int Q = Integer.parseInt(br.readLine().trim());
        StringBuilder sb = new StringBuilder();
        while (Q-- > 0) {
            StringTokenizer st = new StringTokenizer(br.readLine());
            long a = Long.parseLong(st.nextToken()) - 1;
            long b = Long.parseLong(st.nextToken()) - 1;
            long c = Long.parseLong(st.nextToken()) - 1;
            long d = Long.parseLong(st.nextToken()) - 1;
            sb.append(solve(a, b, c, d, 30)).append('\n');
        }
        System.out.print(sb);
    }

    static long solve(long r1, long c1, long r2, long c2, int k) {
        if (k == 0) return 0;
        long half = pow3[k-1];
        int bx1 = (int)(r1/half), by1 = (int)(c1/half);
        int bx2 = (int)(r2/half), by2 = (int)(c2/half);
        long lr1 = r1%half, lc1 = c1%half, lr2 = r2%half, lc2 = c2%half;
        if (bx1==bx2 && by1==by2) return solve(lr1,lc1,lr2,lc2,k-1);
        // BFS on 3x3 grid avoiding (1,1)
        long[][] dist = new long[3][3];
        for (long[] row: dist) Arrays.fill(row, Long.MAX_VALUE/2);
        // dist[bx][by] = min cost to reach sub-block (bx,by) with entry point tracked
        // State: (bx,by, entry_r, entry_c) - too complex, use Dijkstra
        // Actually use Dijkstra with state = (bx,by) and track entry local coords
        long[][][] entR = new long[3][3][1]; long[][][] entC = new long[3][3][1];
        // Use priority queue: (cost, bx, by, local_r, local_c)
        PriorityQueue<long[]> pq = new PriorityQueue<>(Comparator.comparingLong(x->x[0]));
        pq.offer(new long[]{0,bx1,by1,lr1,lc1});
        long[][][][] best = new long[3][3][(int)half+1][(int)Math.min(half,1000)+1];
        // This won't work for large half. Use only sub-block level Dijkstra.
        int[][] dirs = {{-1,0},{1,0},{0,-1},{0,1}};
        Map<Long,Long> visited = new HashMap<>();
        while(!pq.isEmpty()){
            long[] cur = pq.poll();
            long cost=cur[0]; int bx=(int)cur[1],by=(int)cur[2]; long lr=cur[3],lc=cur[4];
            long key = (bx*3L+by)*pow3[k-1]*pow3[k-1]+lr*pow3[k-1]+lc;
            if(visited.containsKey(key)) continue;
            visited.put(key,cost);
            if(bx==bx2&&by==by2){System.out.println("BUG"); return cost+solve(lr,lc,lr2,lc2,k-1);}
            for(int[]d:dirs){int nbx=bx+d[0],nby=by+d[1];if(nbx<0||nbx>2||nby<0||nby>2||(nbx==1&&nby==1))continue;
            long exitR=lr,exitC=lc,entryR,entryC,moveCost;
            if(d[0]==-1){moveCost=lr;entryR=half-1;entryC=lc;}
            else if(d[0]==1){moveCost=half-1-lr;entryR=0;entryC=lc;}
            else if(d[1]==-1){moveCost=lc;entryR=lr;entryC=half-1;}
            else{moveCost=half-1-lc;entryR=lr;entryC=0;}
            pq.offer(new long[]{cost+moveCost+1,nbx,nby,entryR,entryC});}
        }
        return -1;
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static final int MAXK = 30;
    static long[] pow3 = new long[MAXK + 1];

    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    static boolean isWhite(long x, long y) {
        // convert to 0-based
        x--;
        y--;
        for (int k = 0; k < MAXK; k++) {
            long dx = x % 3;
            long dy = y % 3;
            if (dx == 1 && dy == 1) return false;
            x /= 3;
            y /= 3;
            if (x == 0 && y == 0) break;
        }
        return true;
    }

    static int highestDifferentLevel(long x1, long y1, long x2, long y2) {
        // 0-based coordinates
        for (int k = MAXK - 1; k >= 0; k--) {
            long p = pow3[k];
            long ax = x1 / p, ay = y1 / p;
            long bx = x2 / p, by = y2 / p;
            if (ax != bx || ay != by) return k;
        }
        return -1;
    }

    static long solve(long x1, long y1, long x2, long y2) {
        // work with 0-based coordinates
        x1--; y1--; x2--; y2--;

        long ans = 0;

        while (true) {
            if (x1 == x2 && y1 == y2) return ans;

            int k = highestDifferentLevel(x1, y1, x2, y2);
            long size = pow3[k];

            long bx1 = x1 / size, by1 = y1 / size;
            long bx2 = x2 / size, by2 = y2 / size;

            long rx1 = x1 % size, ry1 = y1 % size;
            long rx2 = x2 % size, ry2 = y2 % size;

            // If both points are in same level-k subfractal, continue deeper
            if (bx1 == bx2 && by1 == by2) {
                x1 = rx1;
                y1 = ry1;
                x2 = rx2;
                y2 = ry2;
                continue;
            }

            // At this level, 3x3 arrangement of subblocks of size "size".
            // Since both points are white, neither is in the center block.
            // The adjacency graph among the eight blocks is a cycle.
            // Distance inside fractal equals Manhattan within blocks plus crossing costs.
            //
            // For a point in a block, cost to leave that block through one of its side-adjacent
            // boundaries to neighboring white block equals distance to corresponding side.
            //
            // We model shortest path on the 8-cycle between blocks.

            int id1 = blockId((int) bx1, (int) by1);
            int id2 = blockId((int) bx2, (int) by2);

            long best = Long.MAX_VALUE;

            // clockwise and counterclockwise traversals on the 8-cycle
            best = Math.min(best, pathCost(id1, id2, rx1, ry1, rx2, ry2, size, true));
            best = Math.min(best, pathCost(id1, id2, rx1, ry1, rx2, ry2, size, false));

            return ans + best;
        }
    }

    // cycle order:
    // 0:(0,0) 1:(1,0) 2:(2,0) 3:(2,1) 4:(2,2) 5:(1,2) 6:(0,2) 7:(0,1)
    static int blockId(int bx, int by) {
        if (bx == 0 && by == 0) return 0;
        if (bx == 1 && by == 0) return 1;
        if (bx == 2 && by == 0) return 2;
        if (bx == 2 && by == 1) return 3;
        if (bx == 2 && by == 2) return 4;
        if (bx == 1 && by == 2) return 5;
        if (bx == 0 && by == 2) return 6;
        return 7; // (0,1)
    }

    static int[] bx = {0,1,2,2,2,1,0,0};
    static int[] by = {0,0,0,1,2,2,2,1};

    static long pathCost(int s, int t, long rx1, long ry1, long rx2, long ry2, long size, boolean cw) {
        if (s == t) {
            return solve(rx1 + 1, ry1 + 1, rx2 + 1, ry2 + 1);
        }

        List<Integer> path = new ArrayList<>();
        int cur = s;
        path.add(cur);
        while (cur != t) {
            cur = cw ? (cur + 1) & 7 : (cur + 7) & 7;
            path.add(cur);
        }

        long cost = 0;

        // cost from start point to boundary towards next block
        int n1 = path.get(1);
        cost += distToNeighborBoundary(s, n1, rx1, ry1, size);

        // crossing between intermediate neighboring blocks: 1 step each
        cost += path.size() - 2;

        // cost from entry boundary in target block to target point
        int prev = path.get(path.size() - 2);
        cost += distFromNeighborBoundary(prev, t, rx2, ry2, size);

        return cost;
    }

    static long distToNeighborBoundary(int from, int to, long x, long y, long size) {
        int fx = bx[from], fy = by[from];
        int tx = bx[to], ty = by[to];
        if (fx + 1 == tx) return (size - 1 - x) + 1; // to right edge and cross
        if (fx - 1 == tx) return x + 1;              // to left edge and cross
        if (fy + 1 == ty) return (size - 1 - y) + 1; // to bottom edge and cross
        return y + 1;                                 // to top edge and cross
    }

    static long distFromNeighborBoundary(int from, int to, long x, long y, long size) {
        int fx = bx[from], fy = by[from];
        int tx = bx[to], ty = by[to];
        if (fx + 1 == tx) return x;                  // entered from left edge
        if (fx - 1 == tx) return (size - 1 - x);    // entered from right edge
        if (fy + 1 == ty) return y;                 // entered from top edge
        return (size - 1 - y);                      // entered from bottom edge
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();

        pow3[0] = 1;
        for (int i = 1; i <= MAXK; i++) pow3[i] = pow3[i - 1] * 3L;

        int Q = fs.nextInt();
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < Q; i++) {
            long a = fs.nextLong();
            long b = fs.nextLong();
            long c = fs.nextLong();
            long d = fs.nextLong();
            sb.append(solve(a, b, c, d)).append('\n');
        }
        System.out.print(sb.toString());
    }
}
